/*
 * wide_art.h - 16:9 artwork (title screen, HUD frame) for the wide view, 428 x 200 / 428 x 40.
 * wide_art.c is generated by tools/gen_wide_art.py: it holds only the 54-px side strips and the centre pixels
 * that differ from the original pictures, which come from HOCUS.DAT at run time.
 */
#ifndef HOCUS_WIDE_ART_H
#define HOCUS_WIDE_ART_H
#include <stdint.h>

#define WIDE_ART_SIDE 54
typedef struct { uint16_t x, y; uint8_t c; } WideDelta;   /* centre pixel (0..319, row) -> palette index */

extern const uint8_t   g_wide_title_side[2][200][WIDE_ART_SIDE];
extern const int       g_wide_title_ndelta;
extern const WideDelta g_wide_title_delta[];
extern const uint8_t   g_wide_hud_side[2][40][WIDE_ART_SIDE];
extern const int       g_wide_hud_ndelta;
extern const WideDelta g_wide_hud_delta[];
#endif
